    y = (x << 2) | (b & 0xff) ^ (c >> 1)
    if x > 10:
        return x ** 2
    elif x == 5:
        return y * (a or b) and c
    else:
        for j in range(a, b, c):
            if j % 2 == 0:
                break
            else:
                continue
        return None

